const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const { nanoid } = require('nanoid');
const cors = require('cors');
const path = require('path');

const app = express();
const PORT = 3000;

// Middleware
app.use(express.json());
app.use(cors());
app.use(express.urlencoded({ extended: true }));

// Database connect
const db = new sqlite3.Database('./urls.db');

// Table banayenge
db.run(`CREATE TABLE IF NOT EXISTS urls (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    shortCode TEXT UNIQUE NOT NULL,
    longUrl TEXT NOT NULL,
    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP
)`);

// ========== 1. HTML PAGE SERVE KAREGA ==========
app.get('/', (req, res) => {
    res.send(`
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>Simple URL Shortener</title>
        <style>
            * { margin: 0; padding: 0; box-sizing: border-box; font-family: 'Segoe UI', sans-serif; }
            body {
                background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); /* Purple gradient like image */
                min-height: 100vh;
                display: flex;
                justify-content: center;
                align-items: center;
                padding: 20px;
            }
           .card {
                background: #f5f5f5;
                padding: 40px 35px;
                border-radius: 20px;
                box-shadow: 0 20px 40px rgba(0,0,0,0.2);
                width: 100%;
                max-width: 550px;
                text-align: center;
            }
           .title {
                color: #4a6cf7; /* Blue color */
                font-size: 28px;
                font-weight: 700;
                margin-bottom: 8px;
            }
           .subtitle {
                color: #666;
                font-size: 14px;
                margin-bottom: 25px;
            }
           .input-group {
                display: flex;
                gap: 10px;
            }
            input {
                flex: 1;
                padding: 14px 18px;
                border: 2px solid #ddd;
                border-radius: 10px;
                font-size: 15px;
                outline: none;
            }
            input:focus { border-color: #4a6cf7; }
            button {
                background: linear-gradient(135deg, #4a6cf7 0%, #764ba2 100%); /* Blue to Purple */
                color: white;
                border: none;
                padding: 14px 25px;
                border-radius: 10px;
                font-size: 15px;
                font-weight: 600;
                cursor: pointer;
                transition: 0.3s;
            }
            button:hover { transform: translateY(-2px); }
            #result {
                margin-top: 20px;
                padding: 15px;
                background: #e8f0ff;
                border: 1px dashed #4a6cf7;
                border-radius: 10px;
                display: none;
                word-break: break-all;
            }
            #result a { color: #4a6cf7; font-weight: 600; text-decoration: none; }
        </style>
    </head>
    <body>
        <div class="card">
            <h1 class="title">🚀 Simple URL Shortener</h1>
            <p class="subtitle">Paste your long URL and make it short & clean</p>
            <div class="input-group">
                <input type="text" id="longUrl" placeholder="Enter long URL here...">
                <button onclick="shortenUrl()">Shorten</button>
            </div>
            <div id="result"></div>
        </div>

        <script>
            async function shortenUrl() {
                const longUrl = document.getElementById('longUrl').value;
                const resultDiv = document.getElementById('result');
                if(!longUrl) { alert('Pehle URL enter karo'); return; }

                const res = await fetch('/api/shorten', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ longUrl })
                });
                const data = await res.json();

                if(data.success){
                    resultDiv.style.display = 'block';
                    resultDiv.innerHTML = \`✅ Your Short URL: <br><a href="\${data.shortUrl}" target="_blank">\${data.shortUrl}</a>\`;
                } else {
                    alert(data.error);
                }
            }
        </script>
    </body>
    </html>
    `);
});

// ========== 2. API: SHORT KARNE KE LIYE ==========
app.post('/api/shorten', (req, res) => {
    const { longUrl } = req.body;
    if (!longUrl) {
        return res.status(400).json({ success: false, error: 'URL dena zaroori hai' });
    }
    const shortCode = nanoid(6);
    const sql = `INSERT INTO urls (shortCode, longUrl) VALUES (?,?)`;
    db.run(sql, [shortCode, longUrl], function(err) {
        if (err) return res.status(500).json({ success: false, error: 'Error' });
        const shortUrl = `http://localhost:${PORT}/${shortCode}`;
        res.status(201).json({ success: true, shortUrl: shortUrl });
    });
});

// ========== 3. API: REDIRECT KARNE KE LIYE ==========
app.get('/:shortCode', (req, res) => {
    const { shortCode } = req.params;
    const sql = `SELECT longUrl FROM urls WHERE shortCode =?`;
    db.get(sql, [shortCode], (err, row) => {
        if (err ||!row) return res.status(404).send('URL nahi mili');
        res.redirect(row.longUrl);
    });
});

// Server start
app.listen(PORT, () => {
    console.log(`Server chal gaya: http://localhost:${PORT}`);
});